// Synthetic replica of react-native-gesture-handler@2 sources. The published
// package points its "react-native" / exports condition at TypeScript that
// reaches into a native module. We resolve the native handle off the React
// Native default export so the bundle resolves cleanly; the handle is null at
// build time because the native TurboModule is only registered on a device.
import ReactNative from "react-native";

const RNGestureHandlerModule =
  (ReactNative as { TurboModuleRegistry?: { get(name: string): unknown } }).TurboModuleRegistry?.get(
    "RNGestureHandlerModule",
  ) ?? null;

export const GESTURE_HANDLER_OK = "GESTURE_HANDLER_OK";

export const State = {
  UNDETERMINED: 0,
  FAILED: 1,
  BEGAN: 2,
  CANCELLED: 3,
  ACTIVE: 4,
  END: 5,
} as const;

export function attachGestureHandler(tag: number): boolean {
  if (!RNGestureHandlerModule) {
    return false;
  }
  return true;
}

export function gestureHandlerRootHOC<T>(Component: T): T {
  return Component;
}
